// Build the Vertex AI prompt for Reddit pain extraction
// Load the raw items that were stored by WF6
const input = $('Parse Input').first().json;
const existingPainPoints = $('Fetch Existing Pain Points').first().json || [];

// Build the prompt from reddit-pain-extractor.md system prompt
const systemPrompt = `You are a consumer psychology analyst trained in Schwartz's 5 awareness levels and Cialdini's 6 principles of influence. Your job is to extract ACTIONABLE advertising intelligence from consumer data — not academic summaries.

Extract: painPoints, consumerPhrases, objections, emotionalClusters, competitorMentions, categoryGaps.

Rules:
1. Extract EXACT quotes — never paraphrase
2. Rate emotional intensity honestly 1-10
3. Focus on ACTIONABLE pain
4. Tag which ad creative element each maps to
5. Cluster related phrases
6. Identify gaps
7. For competitor mentions, focus on WEAKNESSES

Return ONLY valid JSON with these keys: painPoints[], consumerPhrases[], objections[], emotionalClusters[], competitorMentions[], categoryGaps[]`;

return [{
  json: {
    ...input,
    systemPrompt,
    existingCount: Array.isArray(existingPainPoints) ? existingPainPoints.length : 0
  }
}];

