// Parse Vertex AI response and structure for backend
const vertexResponse = $input.first().json;
const input = $('Parse Input').first().json;

// Extract text from Gemini response
const text = vertexResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let analysis;
try {
  analysis = JSON.parse(text);
} catch (e) {
  // Try to extract JSON from markdown code blocks
  const match = text.match(/```json?\s*([\s\S]*?)```/);
  if (match) {
    analysis = JSON.parse(match[1]);
  } else {
    analysis = { painPoints: [], consumerPhrases: [], objections: [], competitorMentions: [] };
  }
}

// Map to backend format
const painPoints = (analysis.painPoints || []).map(p => ({
  painPointText: p.painPointText || p.text || p.pain,
  rawQuote: (p.rawQuotes || [])[0] || null,
  source: 'reddit',
  frequency: p.frequency || 1,
  painCategory: p.painCategory || null,
  motivationType: p.motivationType || null,
  emotionalIntensity: p.emotionalIntensity || 5,
  urgencyLevel: p.urgencyLevel || null,
  triggerTypes: p.triggerTypes || null,
  adAngleRelevance: p.adAngleRelevance || null
}));

const phrases = (analysis.consumerPhrases || []).map(p => ({
  phrase: p.phrase,
  source: 'reddit',
  context: p.context || null,
  frequency: p.frequency || 1,
  phraseType: p.phraseType || 'complaint',
  emotionalValence: p.emotionalValence || null,
  emotionalIntensity: p.emotionalIntensity || 5,
  useableAs: p.useableAs || null,
  clusterLabel: p.clusterLabel || null
}));

const competitorMessages = (analysis.competitorMentions || []).map(c => ({
  source: 'reddit',
  headline: c.brand || null,
  primaryClaim: null,
  weaknessIdentified: c.identifiedWeakness || null,
  gapOpportunity: (analysis.categoryGaps || [])[0]?.opportunity || null,
  messagingAngle: null,
  awarenessLevel: null
}));

const objections = (analysis.objections || []).map(o => ({
  objection: o.objection || o.text,
  source: 'reddit',
  rawQuote: (o.rawQuotes || [])[0] || null,
  frequency: o.frequency || 1,
  emotionalIntensity: 5
}));

return [{
  json: {
    candidateId: input.candidateId,
    painPoints,
    phrases,
    competitorMessages,
    objections
  }
}];

